package net.imadz.metarch.application.projection.handlers

import akka.projection.eventsourced.EventEnvelope
import akka.projection.jdbc.scaladsl.JdbcHandler
import javax.inject.{Inject, Singleton}
import net.imadz.common.application.projection.ScalikeJdbcSession
import net.imadz.metarch.infrastructure.proto.concept.ConceptEventPO

import scala.concurrent.ExecutionContext

/**
 * ParkConceptDecisionView 组合分发器：
 * 按事件类型路由到已实现的 per-event handler。
 * 未实现的事件暂跳过（打印一次日志），保证投影流不中断；
 * 对应 handler 落地后在此接入路由。
 */
@Singleton
class ParkConceptDecisionViewCompositeHandler @Inject() (
  established: ParkConceptDecisionViewOnConceptEstablishedHandler
)(implicit ec: ExecutionContext) extends JdbcHandler[EventEnvelope[ConceptEventPO.Event], ScalikeJdbcSession] {

  private val loggedSkips = scala.collection.mutable.Set[String]()

  private def skipLog(what: String): Unit =
    if (!loggedSkips.contains(what)) { loggedSkips += what; System.out.println(s"[park-projection] SKIP $what（handler 未实现，落地后接入路由）") }

  override def process(session: ScalikeJdbcSession, envelope: EventEnvelope[ConceptEventPO.Event]): Unit = {
    envelope.event match {
      // S2-72 B 案：ConceptCreated 分支退役——ConceptEstablished handler 已含出生字段合并语义
      case ConceptEventPO.Event.ConceptEstablished(_) => established.process(session, envelope)
      case ConceptEventPO.Event.ConceptUpdated(_)     => skipLog("ConceptUpdated")
      case ConceptEventPO.Event.ConceptParked(_)      => skipLog("ConceptParked")
      case ConceptEventPO.Event.ConceptUnparked(_)    => skipLog("ConceptUnparked")
      case ConceptEventPO.Event.ConceptDeprecated(_)  => skipLog("ConceptDeprecated")
      case ConceptEventPO.Event.ConceptRemoved(_)     => skipLog("ConceptRemoved")
      case ConceptEventPO.Event.ConceptsMerged(_)     => skipLog("ConceptsMerged")
      case ConceptEventPO.Event.ConceptConflictWarningCreated(_)  => skipLog("ConceptConflictWarningCreated")
      case ConceptEventPO.Event.ConceptConflictWarningResolved(_) => skipLog("ConceptConflictWarningResolved")
      // Relation* 事件属 Relation 聚合独立流（relation.proto / RelationEventPO），不在本 tag 消费范围
      case _ => () // 未知事件类型
    }
  }
}
